(1089, 1, 'TECHNIP/DOF', 'SKAU - TFMC/DOF', 'Aeroporto de Cabo Frio', '{"grupo":"TECHNIP\/DOF","unidade":"SKAU - TFMC\/DOF","data":"2026-09-05","local":"Aeroporto de Cabo Frio","modal":"Helicóptero","preposto":"Ítalo Gabriel","observacao_nome_arquivo":"","horarios":{"saida_hotel":[{"label1":"Previsto TFMC","h1":"05","m1":"30","label2":"Real","h2":"05","m2":"26"},{"label1":"Previsto DOF","h1":"05","m1":"30","label2":"Real","h2":"05","m2":"49"}],"embarque_previsto":"07:30","embarque_real":"08:05","atendimento_inicio":"04:45","atendimento_fim":"12:14"},"info_troca":"<div>Devido às condições meteorológicas desfavoráveis no Aeroporto de Cabo Frio, a programação permaneceu em stand-by.<\/div><div><br><\/div><div>Após a melhora do tempo, o portão de embarque foi solicitado às 08:05h, com decolagem às 09:12h.<\/div><div><br><\/div><div>A troca de turma foi realizada com sucesso.<\/div>","pax_embarcando":"*TFMC*\n1.RAFAEL SOUSA REIS\n\n*DOF*\n2.KAYO HENRIQUE GONCALVES ANTUNES\n3.HARALD JOHAN PILE\n4.ALEXANDER SOUZA BUZAGLO\n5.MARCELO PAES GUIMARAES\n\n*ACV TECHLINE*\n6.CARLA CAROLINE FERREIRA GOMES","pax_desembarcando":"*TFMC*\n1.DEYVERSON QUEIROZ DOS\n2.MILLER BARRETO DUTRA\n3.BRUNO DA SILVA ROSA\n\n*DOF*\n4.MARLEY SIMOES SONCIN\n5.JOHN ANDRE ALSAND LIND\n6.MARCOS PAULO FRANCA\n7.RICHARD DO NASCIMENTO\n\n*TERCEIRIZADOS*\n8.GABRIEL DOS SANTOS PERE\n9.JORGE LUIS VIANA DANTAS\n10.PEDRO MONSORES DORO\n11.RODRIGO TAVARES BARROS","fotos":[]}', 0, NULL, '2026-09-07 18:39:14', '2026-09-07 18:39:14', 'TECHNIP', NULL, 'relatorios_pdf/6a9f04d2bfb55_SKAU_-_TFMC-DOF_05-09-2026_(07:30h).pdf', '2804:18:5845:8a03:6d9e:9e6d:1832:6baf');
